  "repository": {
    "url": "https://github.com/xfloukiex-lab/magpie-search",
    "source": "github"
  },
  "packages": [
    {
      "registryType": "pypi",
      "registryBaseUrl": "https://pypi.org",
      "identifier": "magpie-search",
      "version": "1.2.1",
      "runtimeHint": "uvx",
      "transport": {
        "type": "stdio"
      },
      "packageArguments": [
        {
          "type": "positional",
          "value": "magpie-search-mcp"
